      "causa_raiz": "O tempo de processamento de GPU atingiu 30.19 ms com 514 violações severas do orçamento de 16.7 ms (60 FPS), indicando gargalo crítico de fillrate, shading complexo (pixel/fragment shaders pesados, pós-processamento como SSAO/SSR/Bloom desmedidos) e render resolution estática incompatível com a carga gráfica na GTX 1650.",
      "codigo_refatorado": "using UnityEngine;
using UnityEngine.Rendering;

public class DynamicGpuOptimizer : MonoBehaviour
{
    [Header("Configurações de Resolução Dinâmica")]
    [SerializeField] private float targetFrameRate = 60.0f;
    [SerializeField] private float minRenderScale = 0.65f;
    [SerializeField] private float maxRenderScale = 1.0f;
    [SerializeField] private float scaleStep = 0.05f;
    [SerializeField] private float checkInterval = 0.25f;

    private float currentScale = 1.0f;
    private float timer = 0f;
    private float targetFrameTimeMs;

    private void Awake()
    {
        targetFrameTimeMs = 1000f / targetFrameFrameRateSafe(targetFrameRate);
        currentScale = maxRenderScale;
        ApplyRenderScale(currentScale);
    }

    private float targetFrameFrameRateSafe(float rate)
    {
        return rate > 0f ? rate : 60f;
    }

    private void Update()
    {
        timer += Time.unscaledDeltaTime;
        if (timer < checkInterval) return;

        timer = 0f;
        float currentFrameTimeMs = Time.unscaledDeltaTime * 1000f;

        if (currentFrameTimeMs > targetFrameTimeMs * 1.05f)
        {
            if (currentScale > minRenderScale)
            {
                currentScale = Mathf.Max(minRenderScale, currentScale - scaleStep);
                ApplyRenderScale(currentScale);
            }
        }
        else if (currentFrameTimeMs < targetFrameTimeMs * 0.85f)
        {
            if (currentScale < maxRenderScale)
            {
                currentScale = Mathf.Min(maxRenderScale, currentScale + scaleStep);
                ApplyRenderScale(currentScale);
            }
        }
    }

    private void ApplyRenderScale(float scale)
    {
        ScalableBufferManager.ResizeBuffers(scale, scale);
    }
}",
      "explicacao_didatica": "A placa de vídeo (GPU) estava gastando 30.19 milissegundos para desenhar um único quadro, o que reduz o jogo para aproximadamente 33 quadros por segundo, quebrando a meta de 60 quadros por segundo (máximo de 16.7 milissegundos). Isso ocorre quando a GPU precisa pintar muitos pixels com cálculos visuais complexos ao mesmo tempo. O código acima cria um gerenciador dinâmico de resolução: quando o jogo detecta que a GPU está demorando para entregar o quadro, ele reduz levemente a contagem de pixels desenhados internamente, mantendo a taxa de quadros fluida e estável sem exigir alocação de memória no processo."
    }
